\]

bs_gamma &lt;- function(type, S, K, r, q, tau, sigma, d1, d2) {

  q_df &lt;- exp(-q * tau)

  result &lt;- q_df * phi(d1) / (S * sigma * sqrt(tau))

  return(result)

}


